import { syncSubagentStopDispatcher } from '../../subagent-stop/sync-subagent-stop-dispatcher.js';
import { outputValidator } from '../../subagent-stop/output-validator.js';
import { createTestContext } from '../fixtures/test-context.js';

/**
 * The payload shape Claude Code ACTUALLY sends at SubagentStop: no
 * `agent_output`, no `output`, no `duration_ms`, no `tool_input`. Verified
 * against 11,319 captured rows (#3034). Any test that supplies `agent_output`
 * is testing a payload that does not occur in production.
 */
function realCcSubagentStopInput(overrides: Partial<HookInput> = {}): HookInput {
  return {
    tool_name: 'Task',
    session_id: 'test-session-sync-dispatch',
    subagent_type: 'test-agent',
    last_assistant_message: 'A realistic closing message from the subagent.',
    ...overrides,
  } as HookInput;
}

let testCtx: ReturnType<typeof createTestContext>;

describe('sync-subagent-stop-dispatcher (#3200 regression)', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    testCtx = createTestContext({ logDir: '/test/project/.claude/logs' });
    process.env.CLAUDE_PROJECT_DIR = '/test/project';
  });

  describe('the kill-switch invariant', () => {
    test('does NOT short-circuit on the real CC payload (absent agent_output)', () => {
      // Arrange: exactly what CC sends. No output field at all.
      const input = realCcSubagentStopInput();

      // Act
      const result = syncSubagentStopDispatcher(input, testCtx);

      // Assert: the dispatcher's only early return is continue===false, so
      // anything other than false proves all SYNC_HOOKS were reached.
      expect(result.continue).not.toBe(false);
    });

    test('output-validator alone does not block when the field is absent', () => {
      const input = realCcSubagentStopInput();

      const result = outputValidator(input, testCtx);

      expect(result.continue).not.toBe(false);
      // and it must not claim the agent failed for a field CC never sent
      expect(result.systemMessage ?? '').not.toContain('Agent produced empty output');
    });

    test('an absent field is not reported as a very-short-output warning', () => {
      // Arrange: no result field in any supported name. A DELIVERED short
      // message does warn now that the hook reads last_assistant_message
      // (pinned by output-validator.test.ts T1); absent must not.
      const input = realCcSubagentStopInput({ last_assistant_message: undefined });

      const result = outputValidator(input, testCtx);

      expect(result.systemMessage ?? '').not.toContain('very short');
    });
  });

  describe('the gate still works where it is meaningful', () => {
    // GH-4158: the reader skips empty strings, so an explicitly empty legacy
    // agent_output is indistinguishable from an absent result and must not
    // block. The empty-result signal belongs to empty-result-detector, which
    // sits FIRST in SYNC_HOOKS and warns without blocking (#3200 posture).
    test('an explicitly EMPTY legacy agent_output does not block (reader skips empty strings)', () => {
      const input = realCcSubagentStopInput({ agent_output: '' });

      const result = outputValidator(input, testCtx);

      expect(result.continue).not.toBe(false);
      expect(result.systemMessage ?? '').not.toContain('Errors:');
    });

    test('the dispatcher DOES short-circuit when a hook legitimately blocks', () => {
      // Arrange: no payload can make output-validator block anymore (GH-4158),
      // so the mechanism is probed with a mocked validator that blocks.
      blockValidator.active = true;
      try {
        const input = realCcSubagentStopInput();

        const result = syncSubagentStopDispatcher(input, testCtx);

        expect(result.continue).toBe(false);
      } finally {
        blockValidator.active = false;
      }
    });

    test('a healthy delivered output passes and does not block', () => {
      const input = realCcSubagentStopInput({
        agent_output: 'A sufficiently long and healthy agent output that clears the fifty character minimum.',
      });

      const result = outputValidator(input, testCtx);

      expect(result.continue).not.toBe(false);
    });
  });

  describe('hook ordering is not load-bearing for telemetry', () => {
    test('late hooks are reached on the real payload, whatever the order', () => {
      // Regression intent: if a future hook is inserted early and returns
      // continue:false on a common payload, this fails rather than silently
      // starving telemetry for months.
      const result = syncSubagentStopDispatcher(realCcSubagentStopInput(), testCtx);

      expect(result.continue).not.toBe(false);
    });
  });
});
